class Solution {
public:
    int findMaxK(std::vector<int>& nums) {
        std::unordered_set<int> seen(nums.begin(), nums.end());
        int best = -1;
        for (int x : nums) {
            if (x > 0 && seen.count(-x)) {
                best = std::max(best, x);
            }
        }
        return best;
    }
};

class Solution {
    public int findMaxK(int[] nums) {
        java.util.Set<Integer> seen = new java.util.HashSet<>();
        for (int x : nums) seen.add(x);
        int best = -1;
        for (int x : nums) {
            if (x > 0 && seen.contains(-x)) {
                if (x > best) best = x;
            }
        }
        return best;
    }
}

var findMaxK = function(nums) {
    const seen = new Set(nums);
    let best = -1;
    for (const x of nums) {
        if (x > 0 && seen.has(-x)) {
            if (x > best) best = x;
        }
    }
    return best;
};
